from fractions import Fraction as Fr
expr = "2**(57-33/11*13-2) + 3**(64-56/8*4-44)"
import re
def evaluate(e):
    e = re.sub(r"(\d+)", r"Fr(\1)", e)
    return eval(e, {"Fr": Fr})
def swap(e, a, b):
    return re.sub(r"\d+", lambda m: {a: b, b: a}.get(m.group(), m.group()), e)
pairs = {"A": ("2", "4"), "B": ("56", "57"), "C": ("57", "64"), "D": ("33", "44")}
opts = {k: evaluate(swap(expr, *p)) == 35 for k, p in pairs.items()}
result = True

match = [k for k, v in opts.items() if v == result]
assert len(match) == 1
print(f"ANSWER={match[0]}")

