net = {(0, 0): "@", (0, 1): "#", (1, 1): "%", (2, 1): "€", (3, 1): "∞", (3, 2): "*"}
pos = {v: k for k, v in net.items()}
def opposite(sym):
    r, c = pos[sym]
    for dr, dc in ((2, 0), (-2, 0), (0, 2), (0, -2)):
        mid, far = (r + dr // 2, c + dc // 2), (r + dr, c + dc)
        if mid in net and far in net:
            return net[far]
