parent, spouse, gender = {}, {}, {}
def rel(a, op, b):
    if op == "+": parent.setdefault(b, set()).add(a); gender[a] = "f"
    if op == "-": spouse[a], spouse[b] = b, a; gender[a] = "m"; gender[b] = "f"
    if op == "x": parent.setdefault(b, set()).add(a); gender[a] = "m"
    if op == "/": parent.setdefault(a, set()).add(b); gender[a] = "f"
chain = ["K", "/", "L", "-", "M", "+", "N", "x", "O"]
for i in range(0, len(chain) - 2, 2):
    rel(chain[i], chain[i + 1], chain[i + 2])
for c, ps in parent.items():            # a child of one spouse is the couple's child
    for p in list(ps):
        if p in spouse: ps.add(spouse[p])
def relation(x, y):
    for p in parent.get(y, ()):
        if p != x and parent.get(p) and parent.get(x) and parent[p] & parent[x]:
            return ("Father's" if gender.get(p) == "m" else "Mother's") + (" sister" if gender[x] == "f" else " brother")
